-- ============================================================
-- STRENGTHEN LEGAL PROTECTIONS — Terms of Service & Disclaimer
--
-- Targeted additions (not a rewrite — the existing content was
-- already a solid baseline). Snapshots the prior version into
-- legal_document_revisions before updating, consistent with how
-- the admin editor behaves, so there's a record of exactly what
-- changed and when.
--
-- What was added and why:
-- 1. Explicit "not a registered investment adviser under the
--    Investment Advisers Act of 1940" language, and an explicit
--    "no fiduciary relationship" statement. The prior text said
--    "not financial/investment/tax/legal advice" in general terms,
--    which is good but doesn't use the specific regulatory language
--    that matters if this is ever actually tested.
-- 2. An 18+ age eligibility requirement (was missing entirely).
-- 3. An explicit prohibition on using the Service or AI features to
--    plan or facilitate financial crimes (insider trading, market
--    manipulation, money laundering, tax evasion, securities fraud).
-- 4. A "past performance is not indicative of future results"
--    disclosure in the Disclaimer — standard, expected boilerplate
--    for anything discussing investment concepts.
--
-- IMPORTANT: this is drafted to reduce risk, not eliminate it, and
-- is not a substitute for review by a licensed attorney in your
-- jurisdiction before taking payment from real customers.
-- ============================================================

DO $$
DECLARE
  terms_doc RECORD;
  disc_doc RECORD;
BEGIN
  -- Snapshot current versions before updating
  SELECT * INTO terms_doc FROM legal_documents WHERE slug = 'terms';
  IF FOUND THEN
    INSERT INTO legal_document_revisions (document_id, slug, title, content, version)
    VALUES (terms_doc.id, terms_doc.slug, terms_doc.title, terms_doc.content, terms_doc.version);

    UPDATE legal_documents SET
      title = 'Terms of Service',
      content = '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><p>These Terms of Service (&quot;Terms&quot;) govern your access to and use of Finora (the &quot;Service&quot;), a software product owned and operated by WEALTHOS (&quot;WEALTHOS,&quot; &quot;we,&quot; &quot;us,&quot; or &quot;our&quot;). By creating an account or using the Service, you agree to these Terms. If you do not agree, do not use the Service.</p><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">1. Not Financial, Tax, or Legal Advice</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Finora provides tools for tracking, calculating, and visualizing your own financial information — including the Financial Toolkit&#x27;s calculators, AI Coach, and Support Chat.<strong> Nothing in the Service constitutes financial, investment, tax, or legal advice, or a recommendation to buy, sell, or hold any security or asset.</strong> Calculator outputs and AI responses are estimates based on the assumptions you provide and can be wrong. Always consult a qualified, licensed professional before making financial decisions. <strong>Finora, operated by WEALTHOS, is not a registered investment adviser, broker-dealer, or financial planner under the Investment Advisers Act of 1940 or any comparable state or foreign law, and using the Service does not create an advisory, fiduciary, or client relationship between you and Finora or WEALTHOS.</strong> AI Coach and Support Chat are generated by artificial intelligence, are provided for general education and organizational purposes only, and are not personalized recommendations.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">2. Your Account</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You must provide accurate information and keep your login credentials confidential. You are responsible for all activity under your account. Notify us immediately of any unauthorized use. You must be at least 18 years old to use the Service.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">3. Subscriptions &amp; Billing</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Paid plans renew automatically for the same term until canceled. You can cancel anytime from Settings → Billing; cancellation takes effect at the end of the current billing period, and you retain access until then. See our <a href="/legal/refund-policy" style="color:var(--text-green)">Refund Policy</a> for details on refunds.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">4. Acceptable Use</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You agree not to:</p><ul><li>Use the Service for any unlawful purpose or to violate any applicable law</li><li>Attempt to gain unauthorized access to any account, system, or network related to the Service</li><li>Reverse engineer, scrape, or interfere with the Service&#x27;s normal operation</li><li>Upload malicious code or attempt to disrupt the Service&#x27;s availability</li><li>Use the Service to impersonate any person or entity</li><li>Use the Service, including AI Coach or Support Chat, to plan, facilitate, or seek assistance with insider trading, market manipulation, money laundering, tax evasion, securities fraud, or any other financial crime</li></ul></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">5. User Content</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You retain ownership of the financial data and content you enter into the Service. You grant us a limited license to store, process, and display that content solely to provide the Service to you.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">6. Intellectual Property</h2><div style="display:flex;flex-direction:column;gap:10px"><p>The Service, including its design, code, calculators, and branding, is owned by WEALTHOS and protected by intellectual property laws. See our <a href="/legal/copyright" style="color:var(--text-green)">Copyright Notice</a>. Except as expressly permitted, you may not copy, modify, or create derivative works of the Service.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">7. Third-Party Services</h2><div style="display:flex;flex-direction:column;gap:10px"><p>The Service integrates third-party providers (e.g. payment processing, AI inference, hosting). We are not responsible for the acts or omissions of third parties, though we select providers we believe are reputable and secure.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">8. Disclaimer of Warranties</h2><div style="display:flex;flex-direction:column;gap:10px"><p>THE SERVICE IS PROVIDED &quot;AS IS&quot; AND &quot;AS AVAILABLE,&quot; WITHOUT WARRANTIES OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, AND NON-INFRINGEMENT. WE DO NOT WARRANT THAT THE SERVICE WILL BE UNINTERRUPTED, ERROR-FREE, OR THAT ANY CALCULATION OR AI OUTPUT WILL BE ACCURATE. See our full <a href="/legal/disclaimer" style="color:var(--text-green)">Disclaimer</a>.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">9. Limitation of Liability</h2><div style="display:flex;flex-direction:column;gap:10px"><p>TO THE MAXIMUM EXTENT PERMITTED BY LAW, WEALTHOS SHALL NOT BE LIABLE FOR ANY INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES, OR ANY LOSS OF PROFITS, DATA, OR FINANCIAL LOSS ARISING FROM YOUR USE OF, OR RELIANCE ON, THE SERVICE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGES.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">10. Account Termination</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You may delete your account at any time from Settings. We may suspend or terminate your access if you violate these Terms, engage in fraudulent or abusive behavior, or as required by law.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">11. Governing Law</h2><div style="display:flex;flex-direction:column;gap:10px"><p style="background:rgba(255,159,10,0.08);border:1px solid rgba(255,159,10,0.2);border-radius:8px;padding:10px 14px"><strong>⚠ Placeholder — replace before publishing.</strong> These Terms are governed by the laws of <strong>[Your State/Country]</strong>, without regard to conflict-of-law principles, and any dispute arising from these Terms or the Service will be resolved in the courts located in<strong> [Your City, State/Country]</strong>. Fill in your actual jurisdiction — this depends on where your business is incorporated/operated, which isn&#x27;t something to guess.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">12. Changes to These Terms</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We may update these Terms from time to time. Continued use of the Service after changes take effect constitutes acceptance of the updated Terms.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">13. Contact</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Questions about these Terms? Visit our <a href="/contact" style="color:var(--text-green)">Contact page</a>.</p></div></section>',
      version = terms_doc.version + 1,
      published_at = NOW(),
      updated_at = NOW()
    WHERE slug = 'terms';
  END IF;

  SELECT * INTO disc_doc FROM legal_documents WHERE slug = 'disclaimer';
  IF FOUND THEN
    INSERT INTO legal_document_revisions (document_id, slug, title, content, version)
    VALUES (disc_doc.id, disc_doc.slug, disc_doc.title, disc_doc.content, disc_doc.version);

    UPDATE legal_documents SET
      title = 'Disclaimer',
      content = '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Not Financial, Investment, Tax, or Legal Advice</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Finora is a software tool for tracking, calculating, and visualizing financial information you provide. It is <strong>not</strong> a registered investment adviser, broker-dealer, accountant, or law firm, and nothing on the Service — including dashboard figures, the Financial Toolkit&#x27;s calculators, AI Coach responses, or Support Chat responses — constitutes financial, investment, tax, accounting, or legal advice, or a recommendation to buy, sell, or hold any security, property, or asset. Finora, operated by WEALTHOS, is not a registered investment adviser or broker-dealer under the Investment Advisers Act of 1940 or any comparable state or foreign securities law. No fiduciary relationship is created between you and Finora or WEALTHOS by using the Service. Past performance shown or referenced anywhere in the Service is not indicative of future results.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Calculators &amp; Projections</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Every calculator in the Financial Toolkit (retirement, FIRE, mortgage, rent vs. buy, debt payoff, and others) produces estimates based entirely on the assumptions you enter — expected return, inflation, interest rates, and so on. Real-world results depend on markets, rates, and personal circumstances that cannot be predicted, and actual outcomes will differ, potentially substantially, from any projection shown.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">AI-Generated Content</h2><div style="display:flex;flex-direction:column;gap:10px"><p>AI Coach and Support Chat use large language models to generate responses. These responses can be incomplete, outdated, or simply wrong. AI output should never be your sole basis for a financial decision.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">No Guarantee of Accuracy</h2><div style="display:flex;flex-direction:column;gap:10px"><p>While we aim for accuracy, Finora does not guarantee that any figure, calculation, market data point, or report generated by the Service is complete, current, or error-free.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Your Responsibility</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You are solely responsible for your financial decisions. Before acting on any information from the Service, consult a licensed financial advisor, accountant, or attorney qualified to advise you on your specific situation.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Related Policies</h2><div style="display:flex;flex-direction:column;gap:10px"><p>This Disclaimer supplements our <a href="/legal/terms" style="color:var(--text-green)">Terms of Service</a> and <a href="/legal/privacy" style="color:var(--text-green)">Privacy Policy</a>.</p></div></section>',
      version = disc_doc.version + 1,
      published_at = NOW(),
      updated_at = NOW()
    WHERE slug = 'disclaimer';
  END IF;
END $$;
